def pairwise(grid,target):
    cs=comps_of(grid)
    R=[np.zeros_like(grid,dtype=int) for _ in cs]
    for k,(p,m) in enumerate(cs):
        r0,c0=p; R[k][r0:r0+m.shape[0], c0:c0+m.shape[1]]=m
    th,tw=target.shape
    hits=[]
    for i in range(len(cs)):
        for j in range(i+1,len(cs)):
            for op,F in [('xor',lambda A,B:np.abs(A-B)),('or',lambda A,B:((A+B)>0).astype(int)),('and',lambda A,B:A*B)]:
                G=F(R[i],R[j])
                H,W=G.shape
                for r in range(H-th+1):
                    for c in range(W-tw+1):
                        if np.array_equal(G[r:r+th,c:c+tw],target): hits.append((i,j,op,r,c))
    return hits
